class Employee {
    private String employeeId;
    private String fullName;
    private String department;
    private double baseSalary;
    private int performanceRating; // 1 to 5

    public Employee(String id, String name, String dept, double salary, int rating) {
        this.employeeId = (id != null && !id.trim().isEmpty()) ? id.trim() : "EMP-0000";
        setName(name);
        setDepartment(dept);
        setBaseSalary(salary);
        setPerformanceRating(rating);
    }

    public void setName(String name) {
        if (name != null && !name.trim().isEmpty()) {
            this.fullName = name.trim();
        } else {
            this.fullName = "Unnamed Employee";
        }
    }

    public void setDepartment(String dept) {
        if (dept != null && !dept.trim().isEmpty()) {
            this.department = dept.trim();
        } else {
            this.department = "General";
        }
    }

    public void setBaseSalary(double salary) {
        if (salary >= 1000.0 && salary <= 50000.0) {
            this.baseSalary = salary;
        } else if (salary < 1000.0) {
            this.baseSalary = 1000.0;
        } else {
            this.baseSalary = 50000.0;
        }
    }

    public void setPerformanceRating(int rating) {
        if (rating >= 1 && rating <= 5) {
            this.performanceRating = rating;
        } else {
            this.performanceRating = 3; // Default average
        }
    }

    public boolean giveRaise(double percent) {
        if (percent >= 1.0 && percent <= 30.0) {
            double increase = baseSalary * (percent / 100.0);
            baseSalary += increase;
            return true;
        }
        return false;
    }

    public double calculateAnnualBonus() {
        double annualBase = baseSalary * 12;
        switch (performanceRating) {
            case 5: return annualBase * 0.20;
            case 4: return annualBase * 0.15;
            case 3: return annualBase * 0.10;
            default: return 0.0;
        }
    }

    public double calculateAnnualGrossPay() {
        return (baseSalary * 12) + calculateAnnualBonus();
    }

    public String getEmployeeId() { return employeeId; }
    public String getFullName() { return fullName; }
    public String getDepartment() { return department; }
    public double getBaseSalary() { return baseSalary; }
    public int getPerformanceRating() { return performanceRating; }
}

public class Main {
    public static void main(String[] args) {
        Employee emp = new Employee("EMP-5012", "Aarav Patel", "Cloud Infrastructure", 5000.0, 5);
        System.out.println("Employee: " + emp.getFullName() + " [" + emp.getEmployeeId() + "]");
        System.out.println("Department: " + emp.getDepartment());
        System.out.println("Monthly Salary: $" + emp.getBaseSalary());
        System.out.println("Annual Bonus: $" + emp.calculateAnnualBonus());
        System.out.println("Annual Gross: $" + emp.calculateAnnualGrossPay());

        // Applying 10% raise
        emp.giveRaise(10.0);
        System.out.println("After 10% Raise: $" + emp.getBaseSalary());
    }
}

