    private String department;

    public EmployeeTransfer(String name, String dept) {
        this.name = name;
        this.department = dept;
    }

    public void transferDepartment(String newDept) {
        if (newDept != null && !newDept.trim().isEmpty()) {
            this.department = newDept.trim();
            System.out.println("Transferred to " + this.department);
        }
    }

    public String getDepartment() { return department; }
}

public class Main {
    public static void main(String[] args) {
        EmployeeTransfer emp = new EmployeeTransfer("Rhea", "Support");
        emp.transferDepartment("DevOps");
        System.out.println("Department: " + emp.getDepartment());
    }
}

class EmployeeProfile {
    private String id;
    private String name;
    private double monthlySalary;
    private int rating;

    public EmployeeProfile(String id, String name, double salary, int rating) {
        this.id = id;
        this.name = name;
        this.monthlySalary = salary >= 1000.0 ? salary : 1000.0;
        this.rating = (rating >= 1 && rating <= 5) ? rating : 3;
    }

    public boolean giveRaise(double percent) {
        if (percent >= 1.0 && percent <= 25.0) {
            monthlySalary += monthlySalary * (percent / 100.0);
            return true;
        }
        return false;
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public double getMonthlySalary() { return monthlySalary; }
    public int getRating() { return rating; }
}

public class Main {
    public static void main(String[] args) {
        EmployeeProfile emp = new EmployeeProfile("EMP-1", "Sunil", 4000.0, 4);
        emp.giveRaise(10.0);
        System.out.println(emp.getName() + " [" + emp.getId() + "] Salary: $" + emp.getMonthlySalary());
    }
}

class CompensationManager {
    private double baseMonthlySalary;
    private int performanceRating;

    public CompensationManager(double salary, int rating) {
        this.baseMonthlySalary = salary >= 1000.0 ? salary : 1000.0;
        this.performanceRating = (rating >= 1 && rating <= 5) ? rating : 3;
    }

    public double calculateAnnualBonus() {
        double annualBase = baseMonthlySalary * 12;
        switch (performanceRating) {
            case 5: return annualBase * 0.20;
            case 4: return annualBase * 0.15;
            case 3: return annualBase * 0.10;
            default: return 0.0;
        }
    }

    public double calculateAnnualGross() {
        return (baseMonthlySalary * 12) + calculateAnnualBonus();
    }
}

public class Main {
    public static void main(String[] args) {
        CompensationManager comp = new CompensationManager(5000.0, 5);
        System.out.println("Annual gross: $" + comp.calculateAnnualGross());
    }
}

