class DepartmentPayroll {
    private EmployeeProfile[] staff;

    public DepartmentPayroll(EmployeeProfile[] staff) {
        this.staff = staff != null ? staff.clone() : new EmployeeProfile[0];
    }

    public double calculateTotalMonthlyPayroll() {
        double total = 0.0;
        for (EmployeeProfile e : staff) {
            if (e != null) {
                total += e.getMonthlySalary();
            }
        }
        return total;
    }
}

public class Main {
    public static void main(String[] args) {
        EmployeeProfile e1 = new EmployeeProfile("1", "A", 3000.0, 3);
        EmployeeProfile e2 = new EmployeeProfile("2", "B", 4000.0, 3);
        EmployeeProfile e3 = new EmployeeProfile("3", "C", 5000.0, 3);
        DepartmentPayroll dept = new DepartmentPayroll(new EmployeeProfile[]{e1, e2, e3});
        System.out.println("Total monthly payroll: $" + dept.calculateTotalMonthlyPayroll());
    }
}
